package com.sprintboard;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
@org.junit.jupiter.api.Tag("historical")
@org.springframework.test.context.ActiveProfiles("historical-tests")
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:flowtest;DB_CLOSE_DELAY=-1")
@Transactional
class SprintFlowTest {
 @Autowired WorkspaceService workspace;@Autowired SprintFlowService flow;@Autowired BackupService backups;@Autowired ObjectMapper mapper;@Autowired org.springframework.jdbc.core.JdbcTemplate jdbc;
 @TempDir static Path folder;@DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("sprintboard.backup-directory",()->folder.toString());}
 private final String id="legacy-sprint-14";
 private List<Map<String,Object>> tasks(String sprint){return (List<Map<String,Object>>)workspace.sprint(sprint).get("items");}
 private Map<String,Object> state(String sprint){return (Map<String,Object>)workspace.sprint(sprint).get("flow");}
 private Map<String,Object> regular(){return tasks(id).stream().filter(t->!t.get("externalId").toString().startsWith("BAU-AUTO:")).findFirst().orElseThrow();}
 private String backlog(){return workspace.createBacklog(Map.of("title","Acil iş","size","SMALL","estimatedHours",8,"criteria","Kabul","priority","NORMAL","ownerId","legacy-member-akin")).get("id").toString();}
 private Map<String,Object> add(String sprint,String backlog){var check=(Map<?,?>)workspace.readiness(backlog).get("readiness");return workspace.addTask(sprint,Map.of("backlogId",backlog,"reason","Acil üretim hatası","readinessAcknowledged",true,"readinessFingerprint",check.get("fingerprint")));}
 private Map<String,Object> removeInput(Map<String,Object> t){return Map.of("confirmed",true,"fingerprint",t.get("flowFingerprint"),"reason","Sonraki sprintte planlanacak");}
 private void close(){var p=workspace.closurePreview(id);workspace.completeSprint(id,Map.of("confirmed",true,"fingerprint",p.get("fingerprint"),"carryTaskIds",List.of()));}
 @Test void readsNeverInventHistoricalBaseline(){assertEquals("UNTRACKED",state(id).get("origin"));assertEquals("UNTRACKED",state("legacy-sprint-13").get("origin"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM sprint_flow",Integer.class));}
 @Test void newSprintCapturesStartNotCreation(){close();var s=workspace.createSprint(Map.of("name","Sprint test","start","2026-10-10","end","2026-10-30"));String sid=s.get("id").toString();add(sid,backlog());assertEquals("UNTRACKED",state(sid).get("origin"));workspace.startSprint(sid);assertEquals("START",state(sid).get("origin"));assertEquals(tasks(sid).size(),((List<?>)state(sid).get("baseline")).size());assertEquals(0,((List<?>)state(sid).get("events")).size());}
 @Test void activeAddRequiresReasonAndRecordsOnlyActualChange(){String b=backlog();assertThrows(IllegalArgumentException.class,()->workspace.addTask(id,Map.of("backlogId",b)));assertEquals("UNTRACKED",state(id).get("origin"));int n=tasks(id).size();add(id,b);var s=state(id);assertEquals("OBSERVED",s.get("origin"));assertEquals(n,((List<?>)s.get("baseline")).size());assertEquals(1L,s.get("added"));assertThrows(IllegalArgumentException.class,()->add(id,b));assertEquals(1L,state(id).get("added"));}
 @Test void removalRequiresFreshConfirmationRetainsSnapshotAndAllowsReplan(){var t=regular();String task=t.get("id").toString(),b=t.get("backlogId").toString();assertThrows(IllegalArgumentException.class,()->workspace.removeTask(task,Map.of("reason","Later")));
   var stale=removeInput(t);workspace.updateTask(task,Map.of("status","doing"));assertThrows(IllegalArgumentException.class,()->workspace.removeTask(task,stale));t=tasks(id).stream().filter(x->task.equals(x.get("id"))).findFirst().orElseThrow();var original=mapper.valueToTree(t);workspace.removeTask(task,removeInput(t));assertEquals("Ready",workspace.readiness(b).get("state"));assertEquals(1L,state(id).get("removed"));var e=((List<Map<String,Object>>)state(id).get("events")).getFirst();assertEquals(original,mapper.valueToTree(e.get("task")));add(id,b);assertEquals(1L,state(id).get("added"));assertEquals(1L,state(id).get("removed"));assertNotEquals(task,tasks(id).stream().filter(x->b.equals(x.get("backlogId"))).findFirst().orElseThrow().get("id"));assertEquals(original,mapper.valueToTree(((List<Map<String,Object>>)state(id).get("events")).getFirst().get("task")));}
 @Test void doneAutomaticAndCompletedRemovalAreRejected(){var t=regular();String task=t.get("id").toString();workspace.updateTask(task,Map.of("status","done"));var done=tasks(id).stream().filter(x->task.equals(x.get("id"))).findFirst().orElseThrow();assertThrows(IllegalArgumentException.class,()->workspace.removeTask(task,removeInput(done)));var bau=tasks(id).stream().filter(x->x.get("externalId").toString().startsWith("BAU-AUTO:")).findFirst().orElseThrow();assertThrows(IllegalArgumentException.class,()->workspace.removeTask(bau.get("id").toString(),removeInput(bau)));close();assertThrows(IllegalArgumentException.class,()->workspace.removeTask(task,removeInput(done)));}
 @Test void blockersHaveVersionReasonAndDoNotMoveTasks(){var t=regular();String task=t.get("id").toString();assertThrows(IllegalArgumentException.class,()->flow.setBlocker(task,Map.of("version",0,"blocked",true,"reason"," ")));flow.setBlocker(task,Map.of("version",0,"blocked",true,"reason","Ortam bekleniyor"));assertEquals("todo",jdbc.queryForObject("SELECT status FROM sprint_task WHERE id=?",String.class,task));assertThrows(IllegalArgumentException.class,()->flow.setBlocker(task,Map.of("version",0,"blocked",false,"reason","Çözüldü")));assertThrows(IllegalArgumentException.class,()->workspace.updateTask(task,Map.of("status","done")));workspace.updateTask(task,Map.of("status","doing"));assertEquals(1L,state(id).get("wip"));flow.setBlocker(task,Map.of("version",1,"blocked",false,"reason","Ortam hazır"));workspace.updateTask(task,Map.of("status","done"));assertEquals(0L,state(id).get("blocked"));}
 @Test void leaveAndClosedBlockersRejected(){var leave=tasks(id).stream().filter(x->"LEAVE".equals(x.get("workKind"))).findFirst().orElseThrow();assertThrows(IllegalArgumentException.class,()->flow.setBlocker(leave.get("id").toString(),Map.of("version",0,"blocked",true,"reason","Blocked")));String task=regular().get("id").toString();close();assertThrows(IllegalArgumentException.class,()->flow.setBlocker(task,Map.of("version",0,"blocked",true,"reason","Blocked")));}
 @Test void wipIsWarningAndChangesInvalidateClosePreview(){var before=workspace.closurePreview(id);workspace.configureFlow(id,Map.of("version",0,"wipLimit",1));assertThrows(IllegalArgumentException.class,()->workspace.configureFlow(id,Map.of("version",0,"wipLimit",2)));assertThrows(IllegalArgumentException.class,()->workspace.completeSprint(id,Map.of("confirmed",true,"fingerprint",before.get("fingerprint"),"carryTaskIds",List.of())));var tasks=tasks(id).stream().filter(t->!"LEAVE".equals(t.get("workKind"))).limit(2).toList();for(var t:tasks)workspace.updateTask(t.get("id").toString(),Map.of("status","doing"));assertEquals(2L,state(id).get("wip"));assertEquals(1,state(id).get("wipLimit"));assertThrows(IllegalArgumentException.class,()->workspace.configureFlow(id,Map.of("version",1,"wipLimit",1.5)));}
 @Test void closureKeepsBlockedUndoneAndFreezesFlow(){String task=regular().get("id").toString();flow.setBlocker(task,Map.of("version",0,"blocked",true,"reason","Dış bağımlılık"));workspace.configureFlow(id,Map.of("version",0,"wipLimit",3));close();var frozen=mapper.valueToTree(workspace.sprint(id));assertTrue(frozen.path("items").findValues("blocked").stream().anyMatch(v->v.asBoolean()));assertEquals(1,((Number)state(id).get("blocked")).intValue());assertEquals("undone",jdbc.queryForObject("SELECT status FROM sprint_task WHERE id=?",String.class,task));assertThrows(IllegalArgumentException.class,()->workspace.configureFlow(id,Map.of("version",1,"wipLimit",2)));jdbc.update("UPDATE sprint_flow SET wip_limit=9 WHERE sprint_id=?",id);assertEquals(frozen,mapper.valueToTree(workspace.sprint(id)));}
 @Test void backupRoundTripOldVersionAndTamperValidation(){var old=(ObjectNode)mapper.valueToTree(backups.exportData());old.path("tables").path("leave_record").forEach(r->{((ObjectNode)r).remove("overtime_hours");((ObjectNode)r).remove("overtime_accounting");});((ObjectNode)old.path("tables")).remove("member_photo");old.put("schemaVersion",22);BackupFixtureV40.removeMatching(old);((ObjectNode)old.path("tables")).remove(java.util.List.of("task_activity","overtime_request","leave_request","defect_reserve_link"));((ObjectNode)old.path("tables")).remove("member_participation");((ObjectNode)old.path("tables")).remove("sprint_member_presence");((ObjectNode)old.path("tables")).remove("member_capacity_policy");((ObjectNode)old.path("tables")).remove("sprint_member_policy");for(String table:List.of("sprint_flow","task_blocker","sprint_scope_event"))((ObjectNode)old.path("tables")).remove(table);String b=backlog();add(id,b);String task=regular().get("id").toString();flow.setBlocker(task,Map.of("version",0,"blocked",true,"reason","Ortam"));var snapshot=(ObjectNode)mapper.valueToTree(backups.exportData());var expected=mapper.valueToTree(workspace.sprint(id));restore(old);assertEquals("UNTRACKED",state(id).get("origin"));restore(snapshot);assertEquals(expected,mapper.valueToTree(workspace.sprint(id)));var bad=snapshot.deepCopy();((ObjectNode)bad.path("tables").path("sprint_scope_event").get(0)).put("action","REMOVED");assertThrows(IllegalArgumentException.class,()->backups.preview(bad));}
 private void restore(ObjectNode b){var p=backups.preview(b);backups.restore(mapper.valueToTree(Map.of("backup",b,"confirmation","GERİ YÜKLE","backupFingerprint",p.get("backupFingerprint"),"currentFingerprint",p.get("currentFingerprint"))));}
}
